void check(Solution& solution) {
    assert(solution.removeTrailingZeros("10") == vector<int>1);
    assert(solution.removeTrailingZeros("100100") == vector<int>1001);
    assert(solution.removeTrailingZeros("1111111111") == vector<int>1111111111);
    assert(solution.removeTrailingZeros("1000") == vector<int>1);
    assert(solution.removeTrailingZeros("1") == vector<int>1);
    assert(solution.removeTrailingZeros("9876543210") == vector<int>987654321);
    assert(solution.removeTrailingZeros("10500") == vector<int>105);
    assert(solution.removeTrailingZeros("0") == vector<int>nullptr);
    assert(solution.removeTrailingZeros("51230100") == vector<int>512301);
    assert(solution.removeTrailingZeros("10101000") == vector<int>10101);
    assert(solution.removeTrailingZeros("987654321000") == vector<int>987654321);
    assert(solution.removeTrailingZeros("000000000000000000000") == vector<int>nullptr);
    assert(solution.removeTrailingZeros("123") == vector<int>123);
    assert(solution.removeTrailingZeros("999999999999999999999") == vector<int>999999999999999999999);
    assert(solution.removeTrailingZeros("1000000000000000000001") == vector<int>1000000000000000000001);
    assert(solution.removeTrailingZeros("1010101010") == vector<int>101010101);
    assert(solution.removeTrailingZeros("999999999900") == vector<int>9999999999);
    assert(solution.removeTrailingZeros("10000") == vector<int>1);
    assert(solution.removeTrailingZeros("1001001000") == vector<int>1001001);
    assert(solution.removeTrailingZeros("1000000000") == vector<int>1);
    assert(solution.removeTrailingZeros("100100100") == vector<int>1001001);
    assert(solution.removeTrailingZeros("9999999999") == vector<int>9999999999);
    assert(solution.removeTrailingZeros("00001") == vector<int>00001);
    assert(solution.removeTrailingZeros("100000") == vector<int>1);
}

